queries.LegacyNames:
SELECT Id, Label
FROM Legacy
ORDER BY Id;

queries.LegacyGrouped:
SELECT Label, Count(*) AS Total
FROM Legacy
GROUP BY Label;

queries.LegacySizedParameter:
PARAMETERS selectedName Text ( 8 );
SELECT Id
FROM Legacy
WHERE Label=selectedName;

